True def transform(grid):
    """Fill zero cells from the 180-degree symmetric counterpart."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                out[r][c] = grid[h - 1 - r][w - 1 - c]
    return out
